const medicos = $input.all()
  .map(i => i.json)
  .filter(r => r && r['CD Médico'])
  .map(r => ({
    cd_medico: String(r['CD Médico'] ?? ''),
    nome: String(r['Nome'] ?? ''),
    especialidade: String(r['Especialidade'] ?? ''),
    subespecialidade: String(r['Subespecialidade'] ?? ''),
    telefone: String(r['Telefone'] ?? '').replace(/\D/g,''),
    unidade: String(r['Unidade'] ?? ''),
    ativo: String(r['Ativo'] ?? ''),
    tipo: String(r['Tipo'] ?? '')
  }))
  .filter(m => m.cd_medico && m.ativo.toLowerCase() === 'sim');

return [{ json: { ok: true, medicos } }];

const q = $('API GET Escalas').first().json.query ?? {};
const unidade = String(q.unidade ?? 'Niterói').trim().toLowerCase();
const competencia = String(q.competencia ?? '2026-10').trim();

const escalas = $input.all()
  .map(i => i.json)
  .filter(r => r && r['CD Médico'])
  .map(r => ({
    cd_medico: String(r['CD Médico'] ?? ''),
    nome: String(r['Nome'] ?? ''),
    unidade: String(r['Unidade'] ?? ''),
    competencia: String(r['Competência'] ?? ''),
    dia_semana: String(r['Dia da semana'] ?? ''),
    especialidade: String(r['Especialidade do turno'] ?? ''),
    inicio: String(r['Início'] ?? ''),
    fim: String(r['Fim'] ?? ''),
    almoco: String(r['Almoço'] ?? ''),
    datas_origem: String(r['Datas origem'] ?? ''),
    datas_solicitar: String(r['Datas para solicitar'] ?? ''),
    feriados_removidos: String(r['Feriados removidos'] ?? ''),
    observacao: String(r['Observação'] ?? '')
  }))
  .filter(e =>
    e.unidade.toLowerCase() === unidade &&
    e.competencia === competencia
  );

return [{ json: { ok: true, unidade: q.unidade ?? 'Niterói', competencia, escalas } }];

const q = $('API GET Solicitacoes').first().json.query ?? {};
const unidade = String(q.unidade ?? 'Niterói').trim().toLowerCase();
const competencia = String(q.competencia ?? '2026-10').trim();

const solicitacoes = $input.all()
  .map(i => i.json)
  .filter(r => r && r['ID Solicitação'])
  .map(r => ({
    id_solicitacao: String(r['ID Solicitação'] ?? ''),
    cd_medico: String(r['CD Médico'] ?? ''),
    nome: String(r['Nome'] ?? ''),
    unidade: String(r['Unidade'] ?? ''),
    competencia: String(r['Competência'] ?? ''),
    telefone: String(r['Telefone'] ?? '').replace(/\D/g,''),
    criado_em: String(r['Criado em'] ?? ''),
    status: String(r['Status'] ?? ''),
    enviado_em: String(r['Enviado em'] ?? ''),
    respondido_em: String(r['Respondido em'] ?? ''),
    ultimo_reenvio: String(r['Último reenvio'] ?? ''),
    qtd_reenvios: Number(r['Qtd. reenvios'] ?? 0),
    mensagem_enviada: String(r['Mensagem enviada'] ?? ''),
    resposta_recebida: String(r['Resposta recebida'] ?? ''),
    id_mensagem_resposta: String(r['ID mensagem resposta'] ?? ''),
    evidencia_gerada: String(r['Evidência gerada'] ?? ''),
    observacao_operacional: String(r['Observação operacional'] ?? '')
  }))
  .filter(s =>
    s.unidade.toLowerCase() === unidade &&
    s.competencia === competencia
  );

return [{ json: { ok: true, unidade: q.unidade ?? 'Niterói', competencia, solicitacoes } }];

const body = $('API POST Enviar TESTE').first().json.body ?? {};
const cdSolicitado = String(body.cd_medico ?? '').trim();
const competencia = String(body.competencia ?? '2026-10').trim();

if (!cdSolicitado) {
  return [{json:{autorizado:false,erro:'CD_MEDICO_NAO_INFORMADO',mensagem:'Informe o médico para realizar o envio.'}}];
}

const medRows = $('Sheets TESTE - Ler Medicos').all().map(i => i.json);
const escRows = $('Sheets TESTE - Ler Escalas').all().map(i => i.json);

const med = medRows.find(r => String(r['CD Médico'] ?? '').trim() === cdSolicitado);
if (!med) return [{json:{autorizado:false,erro:'MEDICO_NAO_ENCONTRADO',mensagem:'Médico não encontrado na aba Medicos.'}}];

if (String(med['Ativo'] ?? 'Sim').trim().toLowerCase() !== 'sim') {
  return [{json:{autorizado:false,erro:'MEDICO_INATIVO',mensagem:'O médico está marcado como inativo.'}}];
}

let telefone = String(med['Telefone'] ?? '').replace(/\D/g,'');
if (telefone.length === 11) telefone = `55${telefone}`;

if (telefone.length < 12 || telefone.length > 13) {
  return [{json:{autorizado:false,erro:'TELEFONE_INVALIDO',mensagem:'O telefone cadastrado para este médico é inválido.'}}];
}

const escalas = escRows.filter(r =>
  String(r['CD Médico'] ?? '').trim() === cdSolicitado &&
  String(r['Competência'] ?? '').trim() === competencia
);

if (!escalas.length) {
  return [{json:{autorizado:false,erro:'ESCALA_NAO_ENCONTRADA',mensagem:'Nenhuma escala foi encontrada para este médico nesta competência.',competencia}}];
}

const meses = {'01':'JANEIRO','02':'FEVEREIRO','03':'MARÇO','04':'ABRIL','05':'MAIO','06':'JUNHO','07':'JULHO','08':'AGOSTO','09':'SETEMBRO','10':'OUTUBRO','11':'NOVEMBRO','12':'DEZEMBRO'};
const mes = meses[competencia.split('-')[1]] ?? competencia;
const ordem = ['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];

escalas.sort((a,b) =>
  ordem.indexOf(String(a['Dia da semana'] ?? '')) -
  ordem.indexOf(String(b['Dia da semana'] ?? ''))
);

const blocos = escalas.map(r => {
  let diaBase = String(r['Dia da semana'] ?? '').toUpperCase();
  const dia = /SÁBADO|DOMINGO/.test(diaBase) ? diaBase : `${diaBase}-FEIRA`;
  const datas = String(r['Datas para solicitar'] ?? '').trim();
  const inicio = String(r['Início'] ?? '').trim();
  const fim = String(r['Fim'] ?? '').trim();
  const almoco = String(r['Almoço'] ?? '').trim();

  const linhaAlmoco =
    !almoco ||
    almoco.toLowerCase().includes('sem almoço') ||
    almoco.toLowerCase().includes('não tem')
      ? 'Sem almoço'
      : `Almoço: ${almoco}`;

  return `*${dia}*
${datas}
Horário: ${inicio} às ${fim} hrs
${linhaAlmoco}`;
});

const nomeCompleto = String(med['Nome'] ?? '').trim();
const primeiroNome = nomeCompleto.split(/\s+/)[0] || 'Doutor(a)';
const unidade = String(med['Unidade'] ?? 'Niterói').trim();
const unidadeMensagem = unidade.toUpperCase();

const texto = `Boa tarde, Dr(a). ${primeiroNome}!
Começamos a abertura das

*AGENDAS DE ${mes}*

📌Solicito por gentileza, que me envie os dias e horários que irá atender no ambulatório do CC ${unidadeMensagem}

${blocos.join('\n\n')}

❗Atenção aos FERIADOS e FÉRIAS e datas que desejam realizar o bloqueio das agendas para enviar as datas corretas e evitar cancelamentos após a abertura das agendas.
Por favor, nos envie o mais breve possível. Caso tenha alguma dúvida estou à disposição.`;

return [{json:{
  autorizado:true,
  cd_medico:cdSolicitado,
  nome:nomeCompleto,
  unidade,
  telefone,
  competencia,
  id_solicitacao:`NIT-${competencia}-${cdSolicitado}`,
  texto
}}];

const row = $json ?? {};
const prep = $('Preparar envio TESTE').first().json;

if (!row['ID Solicitação']) {
  return [{json:{atualizar:false,erro:'SOLICITACAO_NAO_ENCONTRADA',envio_whatsapp_ok:true,id_solicitacao:prep.id_solicitacao}}];
}

const agora = new Intl.DateTimeFormat('pt-BR',{
  timeZone:'America/Sao_Paulo',
  year:'numeric',month:'2-digit',day:'2-digit',
  hour:'2-digit',minute:'2-digit',second:'2-digit',
  hour12:false
}).format(new Date());

const enviadoAnterior = String(row['Enviado em'] ?? '').trim();
const jaEnviado = Boolean(enviadoAnterior);

return [{json:{
  atualizar:true,
  id_solicitacao: prep.id_solicitacao,
  cd_medico: String(row['CD Médico'] ?? prep.cd_medico),
  nome: String(row['Nome'] ?? prep.nome),
  unidade: String(row['Unidade'] ?? prep.unidade ?? 'Niterói'),
  competencia: String(row['Competência'] ?? prep.competencia),
  telefone: String(row['Telefone'] ?? prep.telefone).replace(/\D/g,''),
  criado_em: String(row['Criado em'] ?? '') || agora,
  status: 'Aguardando resposta',
  enviado_em: enviadoAnterior || agora,
  respondido_em: '',
  ultimo_reenvio: jaEnviado ? agora : '',
  qtd_reenvios: jaEnviado ? Number(row['Qtd. reenvios'] ?? 0) + 1 : Number(row['Qtd. reenvios'] ?? 0),
  mensagem_enviada: prep.texto,
  observacao_operacional: jaEnviado ? 'Solicitação reenviada pelo painel' : 'Solicitação enviada pelo painel',
  enviado_agora: agora
}}];

const body = $('API POST Obter Evidencia TESTE').first().json.body ?? {};
const cdSolicitado = String(body.cd_medico ?? '').trim();

if (!cdSolicitado) return [{json:{autorizado:false,erro:'CD_MEDICO_NAO_INFORMADO'}}];

const medRows = $('Sheets Evidencia - Ler Medicos').all().map(i => i.json);
const med = medRows.find(r => String(r['CD Médico'] ?? '').trim() === cdSolicitado);

if (!med) return [{json:{autorizado:false,erro:'MEDICO_NAO_ENCONTRADO'}}];
if (String(med['Ativo'] ?? 'Sim').trim().toLowerCase() !== 'sim') {
  return [{json:{autorizado:false,erro:'MEDICO_INATIVO'}}];
}

let telefone = String(med['Telefone'] ?? '').replace(/\D/g,'');
if (telefone.length === 11) telefone = `55${telefone}`;

if (telefone.length < 12 || telefone.length > 13) {
  return [{json:{autorizado:false,erro:'TELEFONE_INVALIDO'}}];
}

return [{json:{
  autorizado:true,
  cd_medico:cdSolicitado,
  nome:String(med['Nome'] ?? ''),
  telefone
}}];

const entrada = $('Evolution MESSAGES_UPSERT - Agenda').first().json ?? {};
const body = entrada.body ?? entrada;

const EVENTO_ESPERADO = 'messages.upsert';
const INSTANCIA_ESPERADA = 'CCNIT';

const evento = String(body.event ?? body.type ?? '').trim().toLowerCase();
const instancia = String(body.instance ?? body.instanceName ?? '').trim();

const data = body.data ?? {};
const key = data.key ?? {};
const fromMe = Boolean(key.fromMe ?? data.fromMe ?? false);

const remoteJidOriginal = String(key.remoteJid ?? data.remoteJid ?? data.sender ?? '').trim();
const remoteJidAlt = String(key.remoteJidAlt ?? data.remoteJidAlt ?? '').trim();
const remoteJid = remoteJidOriginal.endsWith('@lid') && remoteJidAlt ? remoteJidAlt : remoteJidOriginal;

const idMensagem = String(key.id ?? data.id ?? '').trim();

function normalizarTelefone(valor) {
  let telefone = String(valor ?? '').split('@')[0].replace(/\D/g, '');
  if (telefone.length === 11) telefone = `55${telefone}`;
  return telefone;
}

function desembrulharMensagem(msg) {
  let atual = msg ?? {};
  const wrappers = ['ephemeralMessage','viewOnceMessage','viewOnceMessageV2','documentWithCaptionMessage'];
  let mudou = true;
  while (mudou) {
    mudou = false;
    for (const chave of wrappers) {
      if (atual?.[chave]?.message) {
        atual = atual[chave].message;
        mudou = true;
        break;
      }
    }
  }
  return atual;
}

const mensagem = desembrulharMensagem(data.message ?? {});
let texto = String(
  mensagem.conversation ??
  mensagem.extendedTextMessage?.text ??
  mensagem.imageMessage?.caption ??
  mensagem.videoMessage?.caption ??
  mensagem.documentMessage?.caption ??
  mensagem.buttonsResponseMessage?.selectedDisplayText ??
  mensagem.listResponseMessage?.title ??
  mensagem.listResponseMessage?.singleSelectReply?.selectedRowId ??
  mensagem.templateButtonReplyMessage?.selectedDisplayText ??
  ''
).trim();

const messageType = String(data.messageType ?? Object.keys(mensagem ?? {})[0] ?? 'mensagem');
if (!texto) texto = `[Mensagem recebida - ${messageType}]`;

const telefone = normalizarTelefone(remoteJid);
const timestampBruto = Number(data.messageTimestamp ?? body.messageTimestamp ?? 0);
const dataMensagem = Number.isFinite(timestampBruto) && timestampBruto > 0
  ? new Date(timestampBruto > 999999999999 ? timestampBruto : timestampBruto * 1000)
  : new Date();

const recebidoEm = new Intl.DateTimeFormat('pt-BR',{
  timeZone:'America/Sao_Paulo',
  year:'numeric',month:'2-digit',day:'2-digit',
  hour:'2-digit',minute:'2-digit',second:'2-digit',
  hour12:false
}).format(dataMensagem);

let processar = true;
let motivo = '';

if (evento && evento !== EVENTO_ESPERADO) {
  processar = false; motivo = 'EVENTO_IGNORADO';
} else if (instancia && instancia !== INSTANCIA_ESPERADA) {
  processar = false; motivo = 'INSTANCIA_IGNORADA';
} else if (fromMe) {
  processar = false; motivo = 'MENSAGEM_FROM_ME';
} else if (!remoteJid || remoteJid.endsWith('@g.us')) {
  processar = false; motivo = 'JID_INVALIDO_OU_GRUPO';
} else if (!telefone) {
  processar = false; motivo = 'TELEFONE_NAO_IDENTIFICADO';
}

return [{json:{
  processar,
  motivo,
  evento,
  instancia,
  from_me:fromMe,
  remote_jid:remoteJid,
  remote_jid_original:remoteJidOriginal,
  remote_jid_alt:remoteJidAlt,
  telefone,
  texto,
  id_mensagem:idMensagem,
  recebido_em:recebidoEm,
  message_type:messageType
}}];

const msg = $('Interpretar MESSAGES_UPSERT TESTE').first().json;

function normalizarTelefone(valor) {
  let telefone = String(valor ?? '').replace(/\D/g, '');

  if (telefone.length === 11) {
    telefone = `55${telefone}`;
  }

  return telefone;
}

const rows = $input.all().map(i => i.json);

const candidatas = rows.filter(r => {
  const status = String(r['Status'] ?? '').trim().toLowerCase();
  const telefone = normalizarTelefone(r['Telefone']);

  return (
    status === 'aguardando resposta' &&
    telefone === msg.telefone
  );
});

if (!candidatas.length) {
  return [{
    json: {
      atualizar: false,
      erro: 'SOLICITACAO_AGUARDANDO_NAO_ENCONTRADA',
      telefone: msg.telefone,
      resposta_recebida: msg.texto,
      id_mensagem_resposta: msg.id_mensagem
    }
  }];
}

// Se houver mais de uma, usa a última linha encontrada.
// No modelo atual existe uma solicitação por médico/competência.
const row = candidatas[candidatas.length - 1];

return [{
  json: {
    atualizar: true,

    id_solicitacao: String(row['ID Solicitação'] ?? ''),
    cd_medico: String(row['CD Médico'] ?? ''),
    nome: String(row['Nome'] ?? ''),
    unidade: String(row['Unidade'] ?? ''),
    competencia: String(row['Competência'] ?? ''),
    telefone_planilha: String(row['Telefone'] ?? ''),

    criado_em: String(row['Criado em'] ?? ''),
    status: 'Respondido',
    enviado_em: String(row['Enviado em'] ?? ''),
    respondido_em: msg.recebido_em,
    ultimo_reenvio: String(row['Último reenvio'] ?? ''),
    qtd_reenvios: Number(row['Qtd. reenvios'] ?? 0),

    mensagem_enviada: String(row['Mensagem enviada'] ?? ''),
    resposta_recebida: msg.texto,
    id_mensagem_resposta: msg.id_mensagem,
    evidencia_gerada: 'Não',
    observacao_operacional: String(row['Observação operacional'] ?? '')
  }
}];

parameters.content:
## Respostas WhatsApp — TESTE
Webhook: `POST /webhook/agenda-resposta-whatsapp`

Evento esperado da Evolution: `MESSAGES_UPSERT` (`messages.upsert` no payload).

O fluxo:
1. ignora `fromMe=true`, grupos e outros eventos;
2. mantém trava no telefone teste `5521984142559`;
3. procura uma solicitação com status **Aguardando resposta**;
4. muda para **Respondido**;
5. grava **Respondido em**, **Resposta recebida**, **ID mensagem resposta** e `Evidência gerada = Não`.

Observação: o webhook da Evolution precisa efetivamente entregar `MESSAGES_UPSERT` a esta rota, ou o receptor atual precisa encaminhar o evento para ela.

