const q = $('API GET Preview Imagem TESTE').first().json.query ?? {};
const arquivo = String(q.arquivo ?? '').trim();
if (!/^preview-\d{12,13}-\d+\.png$/.test(arquivo)) {
  throw new Error('ARQUIVO_PREVIEW_INVALIDO');
}
return [{json:{arquivo}}];

const d = $json ?? {};
const filename = String(d.filename ?? '');
return [{json:{
  ...d,
  preview_url: filename
    ? `/api/agenda-preview-imagem?arquivo=${encodeURIComponent(filename)}`
    : ''
}}];

const d = $json ?? {};
const filename = String(d.filename ?? '');
return [{json:{
  ...d,
  preview_url: filename
    ? `/api/agenda-preview-imagem?arquivo=${encodeURIComponent(filename)}`
    : ''
}}];

const body = $('API POST Preview Iniciar TESTE').first().json.body ?? {};
const cd = String(body.cd_medico ?? '').trim();

if (!cd) return [{json:{autorizado:false,erro:'CD_MEDICO_NAO_INFORMADO'}}];

const medRows = $input.all().map(i => i.json);
const med = medRows.find(r => String(r['CD Médico'] ?? '').trim() === cd);

if (!med) return [{json:{autorizado:false,erro:'MEDICO_NAO_ENCONTRADO'}}];
if (String(med['Ativo'] ?? 'Sim').trim().toLowerCase() !== 'sim') {
  return [{json:{autorizado:false,erro:'MEDICO_INATIVO'}}];
}

let telefone = String(med['Telefone'] ?? '').replace(/\D/g,'');
if (telefone.length === 11) telefone = `55${telefone}`;

if (telefone.length < 12 || telefone.length > 13) {
  return [{json:{autorizado:false,erro:'TELEFONE_INVALIDO'}}];
}

return [{json:{autorizado:true,cd_medico:cd,telefone,nome:String(med['Nome'] ?? '')}}];

const q = $('API GET Competencias').first().json.query ?? {};
const unidade = String(q.unidade ?? 'Niterói').trim().toLowerCase();
const marcoInicial = '2026-10';

const competencias = [...new Set(
  $input.all()
    .map(i => i.json)
    .filter(r =>
      String(r['Unidade'] ?? '').trim().toLowerCase() === unidade &&
      String(r['Competência'] ?? '').trim() >= marcoInicial &&
      String(r['CD Médico'] ?? '').trim()
    )
    .map(r => String(r['Competência'] ?? '').trim())
    .filter(Boolean)
)].sort();

return [{ json: {
  ok: true,
  unidade: q.unidade ?? 'Niterói',
  marco_inicial: marcoInicial,
  competencias
}}];

const body = $('API POST Salvar Medico').first().json.body ?? {};
const cd = String(body.cd_medico ?? '').trim();
const nome = String(body.nome ?? '').trim();
const telefone = String(body.telefone ?? '').replace(/\D/g,'');
if (!cd) throw new Error('CD Médico não informado.');
if (!nome) throw new Error('Nome do médico não informado.');
if (!telefone) throw new Error('Telefone do médico não informado.');

return [{ json: {
  'CD Médico': cd,
  'Nome': nome,
  'Especialidade': String(body.especialidade ?? '').trim(),
  'Subespecialidade': String(body.subespecialidade ?? '').trim(),
  'Telefone': telefone,
  'Unidade': String(body.unidade ?? 'Niterói').trim(),
  'Ativo': String(body.ativo ?? 'Sim').trim() || 'Sim',
  'Tipo': String(body.tipo ?? '').trim()
}}];

const body = $('API POST Status Medico').first().json.body ?? {};
const cd = String(body.cd_medico ?? '').trim();
const ativo = String(body.ativo ?? '').trim();
if (!cd) throw new Error('CD Médico não informado.');
if (!['Sim','Não','Nao','sim','não','nao'].includes(ativo)) throw new Error('Status inválido.');
return [{json:{'CD Médico':cd,'Ativo':/^s/i.test(ativo)?'Sim':'Não'}}];

const body = $('API POST Confirmar Escala').first().json.body ?? {};
const obrigatorios = ['cd_medico','nome','competencia','dia_semana','inicio','fim'];
for (const campo of obrigatorios) {
  if (!String(body[campo] ?? '').trim()) throw new Error(`Campo obrigatório ausente: ${campo}`);
}
if (!/^\d{4}-\d{2}$/.test(String(body.competencia))) throw new Error('Competência inválida.');

return [{json:{
  'CD Médico': String(body.cd_medico).trim(),
  'Nome': String(body.nome).trim(),
  'Unidade': String(body.unidade ?? 'Niterói').trim(),
  'Competência': String(body.competencia).trim(),
  'Dia da semana': String(body.dia_semana).trim(),
  'Especialidade do turno': String(body.especialidade ?? '').trim(),
  'Início': String(body.inicio).trim(),
  'Fim': String(body.fim).trim(),
  'Almoço': String(body.almoco ?? 'Sem almoço').trim() || 'Sem almoço',
  'Datas origem': String(body.datas_origem ?? '').trim(),
  'Datas para solicitar': String(body.datas_solicitar ?? '').trim(),
  'Feriados removidos': String(body.feriados_removidos ?? '').trim(),
  'Observação': String(body.observacao ?? '').trim()
}}];
